// index.js
import React from 'react';
import ReactDOM from 'react-dom';
import 'carbon-components/css/carbon-components.min.css';
import { MultiSelect } from 'carbon-components-react';

const items = [
  { id: 'option-0', text: 'An example option that is really long to show what should be done to handle long text' },
  { id: 'option-1', text: 'Option 1' },
  { id: 'option-2', text: 'Option 2' },
  { id: 'option-3', text: 'Option 3' },
  { id: 'option-4', text: 'Option 4' },
  { id: 'option-5', text: 'Option 5' },
];

function App() {
  const [selectedItems, setSelectedItems] = React.useState([]);
  const handleChange = ({ selectedItems }) => {
    setSelectedItems(selectedItems);
  };

  return (
    <div style={{ width: '300px', margin: '3em' }}>
      <MultiSelect
        id="carbon-multiselect-example"
        titleText="Multiselect title"
        helperText="Filterable example"
        label="Filter"
        items={items}
        initialSelectedItems={[]}
        selectedItems={selectedItems}
        onChange={handleChange}
        type="filterable"
        itemToString={item => (item ? item.text : '')}
      />
    </div>
  );
}

ReactDOM.render(<App />, document.getElementById('root'));
